<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>SJR | Persiapan Teknis Produksi V1</title><style>
:root{font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#182b49;background:#f3f6fb}*{box-sizing:border-box}body{margin:0}button,input,textarea,select{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #a9c8ff;outline-offset:2px}.app{display:flex;min-height:100vh}.side{width:218px;flex-shrink:0;background:#102343;color:#d8e8ff;padding:24px 14px;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:11px;font-size:14px;font-weight:800}.logo{display:grid;place-items:center;width:39px;height:39px;background:#3078eb;color:#fff;border-radius:11px}.brand small{font-size:11px;font-weight:400;color:#9eb7d8}.cap{font-size:10px;letter-spacing:2px;color:#a6bcda;margin:45px 11px 12px}.nav{border-radius:9px;padding:13px;background:#264675;font-size:13px;font-weight:700}.sidefoot{margin-top:auto;color:#9cb5d5;font-size:11px;line-height:1.8;border-top:1px solid #3b516d;padding-top:13px}.main{min-width:0;flex:1}.top{height:69px;background:white;border-bottom:1px solid #e1e9f3;padding:0 30px;display:flex;align-items:center;justify-content:space-between}.top b{font-size:13px}.top p{font-size:11px;color:#7387a6;margin:4px 0}.demo{font-size:11px;color:#2461bf;background:#eaf2ff;border-radius:30px;padding:9px 12px;font-weight:800}.wrap{padding:24px 26px 42px;max-width:1540px;margin:auto}.eyebrow{font-size:10px;color:#246be5;font-weight:850;letter-spacing:2px}.head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin:10px 0 22px}.head h1{font-size:28px;letter-spacing:-.8px;margin:6px 0}.muted{color:#7487a4;font-size:12px}.status{display:inline-block;border-radius:40px;padding:6px 10px;font-size:11px;font-weight:800;background:#e1f3e8;color:#168049}.btn{border:1px solid #cfddf1;border-radius:9px;background:#fff;color:#1c58b5;padding:11px 15px;font-size:12px;font-weight:800;display:inline-flex;gap:8px;align-items:center;justify-content:center}.btn.primary{background:#286be6;color:#fff;border-color:#286be6}.btn.good{background:#177a55;color:#fff;border-color:#177a55}.btn.ghost{background:#f3f7fe}.btn:disabled{opacity:.5;cursor:not-allowed}.columns{display:grid;grid-template-columns:minmax(0,1.85fr) minmax(295px,.95fr);gap:16px;align-items:start}.stack{display:grid;gap:16px}.card{background:white;border:1px solid #dbe6f4;border-radius:15px;padding:20px;box-shadow:0 7px 22px rgba(21,52,94,.025)}.card h2{font-size:15px;margin:0 0 16px;display:flex;align-items:center;gap:9px}.ic{display:inline-grid;place-items:center;background:#eaf2ff;color:#286be6;width:31px;height:31px;border-radius:9px}.info-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.info{background:#f5f8fd;border:1px solid #e3ebf7;border-radius:9px;padding:12px;min-width:0}.info small{color:#7386a4;font-size:10px}.info strong{display:block;font-size:12px;margin-top:5px;overflow-wrap:anywhere}.brief{background:#f6f9ff;border:1px solid #e2eafa;padding:14px;border-radius:9px;font-size:13px;line-height:1.7;margin-top:14px}.softbar{background:#eaf3ff;color:#285eac;border-radius:9px;padding:11px 13px;font-size:12px;margin-bottom:17px}.sub{color:#778aa7;font-size:12px;line-height:1.6;margin:-5px 0 16px}.smalltitle{font-size:12px;font-weight:800;margin:18px 0 10px}.table-scroll{overflow:auto;border:1px solid #dfe9f5;border-radius:10px}table{width:100%;border-collapse:collapse;min-width:630px}th{background:#f1f6fc;text-align:left;font-size:10px;color:#6b809f;padding:12px 10px}td{padding:10px;border-top:1px solid #e9eef7;vertical-align:top}td input,td select{width:100%;min-width:70px;padding:9px;border:1px solid #d9e5f4;border-radius:7px;background:white;color:#213958;font-size:12px}td .rm{background:#fff0f0;color:#ba4141;border:1px solid #f2d7d7;border-radius:8px;padding:9px}.add{margin-top:10px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:13px}label{display:block;font-size:11px;font-weight:750;color:#526b8d;margin-bottom:6px}textarea,.form-input{width:100%;border-radius:9px;border:1px solid #d6e2f2;padding:11px;color:#243b5e;background:#fff;font-size:13px}textarea{resize:vertical;min-height:94px}.mutebox{background:#f5f8fd;border:1px solid #e5edf7;border-radius:9px;padding:13px;font-size:12px;line-height:1.7}.file{display:flex;align-items:center;gap:10px;padding:11px;border:1px solid #e0e9f6;border-radius:10px;margin-bottom:8px}.fileicon{width:41px;height:42px;flex-shrink:0;display:grid;place-items:center;border-radius:9px;background:#ffefef;color:#b63842;font-size:10px;font-weight:900}.fileicon.zip{background:#f1eaff;color:#7755cf}.filename{font-size:11px;font-weight:750;overflow-wrap:anywhere}.file small{display:block;color:#8192ab;font-size:10px;margin-top:4px}.timeline{border-left:2px solid #cfe1ff;padding-left:15px;margin-left:5px}.event{position:relative;font-size:12px;padding:0 0 20px}.event:before{content:'';position:absolute;left:-22px;top:2px;width:10px;height:10px;border-radius:50%;background:#3981f7;border:3px solid white;box-shadow:0 0 0 1px #b7d0fb}.event small{display:block;color:#8296b2;margin-top:4px}.actions{display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap;margin-top:15px}.hint{font-size:11px;color:#7188a5}.toast{display:none;border-radius:10px;padding:12px 15px;margin-bottom:14px;font-size:12px;background:#e8f8ef;border:1px solid #b8ebcd;color:#1b7b4e}.toast.show{display:block}.check{display:flex;align-items:flex-start;gap:8px;margin:10px 0;font-size:12px;color:#526c8d}.check input{margin-top:3px}.chip{background:#fff2df;color:#9a5e0a;border:1px solid #f1d6a8;padding:8px 11px;border-radius:9px;font-size:11px;font-weight:800;display:inline-block}.count{font-size:11px;background:#ecf3ff;border-radius:20px;padding:5px 9px;color:#285cb0;margin-left:auto}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.sumitem{border:1px solid #e0eafa;padding:12px;border-radius:9px}.sumitem b{display:block;font-size:20px;margin-top:5px}.sumitem small{font-size:10px;color:#7589a6}.btnline{display:flex;flex-wrap:wrap;gap:8px}.hidden{display:none!important}@media(max-width:1050px){.info-grid{grid-template-columns:repeat(2,1fr)}.columns{grid-template-columns:1fr}.side{width:184px}.wrap{padding:21px 15px}}@media(max-width:700px){.app{display:block}.side{width:100%;padding:10px 15px}.side .cap,.side .nav,.sidefoot{display:none}.top{height:auto;padding:14px}.wrap{padding:16px 11px}.head{align-items:flex-start;flex-direction:column}.formgrid{grid-template-columns:1fr}}
</style></head><body><div class="app"><aside class="side"><div class="brand"><div class="logo">S</div><div>Enterprise BPM<br><small>Simple Job Request</small></div></div><div class="cap">PRODUCTION SJR</div><div class="nav">▦ &nbsp; Persiapan Teknis</div><div class="sidefoot">PREVIEW UI · V1<br>Simulasi, tanpa penyimpanan ke Laravel.<br>Alur PROD lama tidak berubah.</div></aside><main class="main"><header class="top"><div><b>Simple Job Request / Production Workspace</b><p>Brief Review → Persiapan Teknis → Kalkulasi HPP → Persetujuan</p></div><span class="demo">UI PREVIEW · DATA SIMULASI</span></header><div class="wrap"><div class="eyebrow">PRODUKSI / PERSIAPAN TEKNIS / SJR-2026-00004</div><div class="head"><div><h1>EG Dove</h1><div class="muted">Indicia · Target 28/11/2026 &nbsp; <span class="status" id="status">Siap Persiapan Teknis</span></div></div><button class="btn" onclick="window.scrollTo({top:0,behavior:'smooth'})">↑ Kembali ke atas</button></div><div id="toast" class="toast" role="status"></div><div class="columns"><div class="stack"><section class="card"><h2><span class="ic">▤</span> Ringkasan Brief Marketing</h2><div class="info-grid"><div class="info"><small>Nomor SJR</small><strong>SJR-2026-00004</strong></div><div class="info"><small>Klien</small><strong>Indicia</strong></div><div class="info"><small>PIC Pelanggan</small><strong>Pak Andi</strong></div><div class="info"><small>Kuantitas Pesanan</small><strong>4 unit</strong></div></div><div class="smalltitle">Detail Brief / Spesifikasi</div><div class="brief">Pembuatan display EG Dove. Material, dimensi dan konstruksi mengikuti brief Marketing dan referensi lampiran. Pastikan ukuran akhir serta metode kerja dicatat dalam persiapan teknis.</div><div class="smalltitle">Brief Designer</div><div class="mutebox">Buatkan technical drawing sesuai hasil survei. <span class="chip">Desain Disetujui Marketing</span></div></section><section class="card"><h2><span class="ic">▦</span> Persiapan Teknis <span class="count">Penyederhanaan PROD-06 & PROD-07</span></h2><div class="softbar">Brief sudah dikonfirmasi cukup jelas. Lengkapi kebutuhan teknis sebagai dasar penyusunan HPP berikutnya.</div><div class="smalltitle">A. Kebutuhan Material</div><p class="sub">Isi material, spesifikasi, satuan, dan kebutuhan total. Harga material dihitung pada tahap HPP, bukan di sini.</p><div class="table-scroll"><table><thead><tr><th style="width:25%">Nama Material</th><th>Spesifikasi / Ukuran</th><th style="width:12%">Satuan</th><th style="width:12%">Jumlah</th><th style="width:55px">Aksi</th></tr></thead><tbody id="materials"></tbody></table></div><button class="btn add" onclick="addRow('materials')">＋ Tambah Material</button><div class="smalltitle">B. Proses / Jasa</div><p class="sub">Catat kebutuhan proses pengerjaan atau jasa eksternal yang akan dihitung biayanya pada tahap HPP.</p><div class="table-scroll"><table><thead><tr><th style="width:30%">Proses / Jasa</th><th>Deskripsi Pekerjaan</th><th style="width:12%">Satuan</th><th style="width:12%">Jumlah</th><th style="width:55px">Aksi</th></tr></thead><tbody id="processes"></tbody></table></div><button class="btn add" onclick="addRow('processes')">＋ Tambah Proses / Jasa</button><div class="smalltitle">C. Instruksi Teknis & Metode Kerja</div><textarea id="instructions" placeholder="Jelaskan urutan proses, konstruksi, toleransi ukuran, finishing, pemeriksaan kualitas, dan catatan khusus..."></textarea><div class="smalltitle">D. Estimasi Leadtime</div><div class="formgrid"><div><label for="leadtime">Estimasi durasi (hari kerja)</label><input id="leadtime" class="form-input" type="number" min="1" placeholder="Contoh: 7"></div><div><label for="leadnote">Catatan waktu / ketergantungan</label><input id="leadnote" class="form-input" placeholder="Contoh: setelah material tersedia"></div></div><div class="actions"><div class="btnline"><button class="btn ghost" onclick="saveDraft()">Simpan Draft (Simulasi)</button><button class="btn primary" onclick="review()">Periksa Kesiapan HPP →</button></div><span class="hint">Belum ada data tersimpan di server</span></div><div id="ready" class="hidden"><hr style="border:0;border-top:1px solid #e4ebf5;margin:22px 0"><h2>Ringkasan Kesiapan HPP</h2><div class="summary"><div class="sumitem"><small>Jenis Material</small><b id="nmaterial">0</b></div><div class="sumitem"><small>Proses / Jasa</small><b id="nprocess">0</b></div><div class="sumitem"><small>Estimasi Leadtime</small><b id="nlead">–</b></div></div><label class="check"><input type="checkbox" id="ack"> Saya telah memeriksa kebutuhan teknis dan siap meneruskannya sebagai dasar kalkulasi HPP.</label><button class="btn good" onclick="advance()">Konfirmasi Siap Hitung HPP →</button><p class="hint">Tindakan ini hanya simulasi perubahan status; modul HPP belum diimplementasikan.</p></div></section></div><div class="stack"><section class="card"><h2><span class="ic">▣</span> Lampiran Referensi <span class="count">2 file contoh</span></h2><div class="file"><div class="fileicon">PDF</div><div><div class="filename">Brief_Spesifikasi_EG_Dove.pdf</div><small>Contoh file · Tidak dapat diunduh pada preview</small></div></div><div class="file"><div class="fileicon zip">ZIP</div><div><div class="filename">Technical_Reference.zip</div><small>Contoh file · Tidak dapat diunduh pada preview</small></div></div></section><section class="card"><h2><span class="ic">✦</span> Hasil Desain Disetujui</h2><div class="mutebox">Referensi desain final Marketing akan ditampilkan di sini dari database SJR pada saat integrasi Laravel.</div></section><section class="card"><h2><span class="ic">◷</span> Riwayat Aktivitas</h2><div class="timeline" id="history"><div class="event"><strong>Brief dinyatakan cukup jelas</strong><small>Produksi · Simulasi</small></div><div class="event"><strong>Desain disetujui Marketing</strong><small>SJR-2026-00004</small></div><div class="event"><strong>Brief dikirim ke Produksi</strong><small>Contoh alur serah-terima</small></div></div></section><section class="card"><h2><span class="ic">ⓘ</span> Batas Tahap Ini</h2><div class="mutebox">Persiapan Teknis hanya menentukan <b>apa yang dibutuhkan</b> dan <b>bagaimana pekerjaan direncanakan</b>. Harga satuan, biaya tenaga kerja, biaya proses, total HPP, serta approval Manager Produksi dilakukan pada tahap berikutnya.</div></section></div></div></div></main></div><script>
const configs={materials:[{a:'PVC Board',b:'5 mm, ukuran mengikuti drawing',u:'lembar',q:'4'},{a:'Sticker cetak UV',b:'Finishing sesuai desain final',u:'m²',q:'5'}],processes:[{a:'Cetak UV',b:'Cetak visual display',u:'m²',q:'5'},{a:'Perakitan',b:'Assembly dan finishing',u:'unit',q:'4'}]};
function esc(s){return String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}function addRow(which,values){const v=values||{a:'',b:'',u:'',q:''};let tr=document.createElement('tr');for(let k of ['a','b','u','q']){let td=document.createElement('td'),inp=document.createElement('input');inp.value=v[k]||'';inp.dataset.field=k;inp.setAttribute('aria-label',({a:'Nama',b:'Spesifikasi',u:'Satuan',q:'Jumlah'})[k]);if(k==='q'){inp.type='number';inp.min='0.01';inp.step='any'}td.appendChild(inp);tr.appendChild(td)}let td=document.createElement('td'),btn=document.createElement('button');btn.className='rm';btn.textContent='×';btn.title='Hapus baris';btn.setAttribute('aria-label','Hapus baris');btn.onclick=()=>tr.remove();td.appendChild(btn);tr.appendChild(td);document.getElementById(which).appendChild(tr)}for(let [key,rows] of Object.entries(configs))rows.forEach(row=>addRow(key,row));
function grab(which){return [...document.querySelectorAll('#'+which+' tr')].map(row=>{let obj={};row.querySelectorAll('input').forEach(inp=>obj[inp.dataset.field]=inp.value.trim());return obj})}function toast(m,error=false){let el=document.getElementById('toast');el.textContent=m;el.style.background=error?'#fff1ef':'#e8f8ef';el.style.borderColor=error?'#f3bfba':'#b8ebcd';el.style.color=error?'#a14136':'#1b7b4e';el.classList.add('show');el.scrollIntoView({behavior:'smooth',block:'nearest'})}function saveDraft(){toast('Draft tersimpan hanya dalam simulasi halaman ini. Data tidak dikirim ke Laravel.')}function review(){let m=grab('materials'),p=grab('processes'),invalid=[...m,...p].some(x=>!x.a||!x.u||!x.q||Number(x.q)<=0);if(!m.length||!p.length||invalid||!document.getElementById('instructions').value.trim()||Number(document.getElementById('leadtime').value)<=0){toast('Lengkapi minimal satu material, satu proses/jasa, instruksi teknis, dan estimasi leadtime. Setiap baris harus memiliki nama, satuan, dan jumlah positif.',true);return}document.getElementById('nmaterial').textContent=m.length;document.getElementById('nprocess').textContent=p.length;document.getElementById('nlead').textContent=document.getElementById('leadtime').value+' hari';document.getElementById('ready').classList.remove('hidden');document.getElementById('ready').scrollIntoView({behavior:'smooth',block:'start'})}function advance(){if(!document.getElementById('ack').checked){toast('Centang konfirmasi kesiapan terlebih dahulu.',true);return}document.getElementById('status').textContent='Siap Hitung HPP · Simulasi';let ev=document.createElement('div');ev.className='event';ev.innerHTML='<strong>Persiapan teknis dikonfirmasi siap HPP</strong><small>Produksi · Simulasi lokal, tidak tersimpan</small>';document.getElementById('history').prepend(ev);toast('Simulasi berhasil: pekerjaan siap menuju Kalkulasi HPP. Belum ada perubahan pada database.')}
</script></body></html>
